import { createElement } from '@wordpress/element';
import { ToggleControl } from '@wordpress/components';
import { __ } from '@wordpress/i18n';

export function FeatureSwitch({ settings, setSettings }) {
  return (
    <ToggleControl
      label={__('Enable this feature', 'ohmylms')}
      checked={settings.feature_enabled === undefined || Boolean(settings.feature_enabled)}
      onChange={(feature_enabled) => setSettings({ ...settings, feature_enabled })}
    />
  );
}
