import { createElement, useEffect, useState } from '@wordpress/element';
import {
  Button,
  ToggleControl,
  TextControl,
  SelectControl,
  Notice,
  Spinner,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';

export function StreakSettings() {
  const [settings, setSettings] = useState(null);
  const [badges, setBadges] = useState([]);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState(null);
  const set = (key, value) => setSettings((previous) => ({ ...previous, [key]: value }));
  useEffect(() => {
    Promise.all([
      window.wp.apiFetch({ path: '/ohmylms/v1/engagement/settings/streak' }),
      window.wp.apiFetch({ path: '/ohmylms/v1/engagement/badges?include_streak=1' }),
    ])
      .then(([value, available]) => {
        setSettings(value);
        setBadges(available);
      })
      .catch((error) => setMessage({ status: 'error', text: error.message }));
  }, []);
  if (!settings)
    return message ? (
      <Notice status="error" isDismissible={false}>
        {message.text}
      </Notice>
    ) : (
      <Spinner />
    );
  const number = (key, label, min, max) => (
    <TextControl
      key={key}
      type="number"
      label={__(label, 'ohmylms')}
      min={min}
      max={max}
      value={settings[key]}
      onChange={(value) => set(key, value === '' ? '' : Number(value))}
    />
  );
  return (
    <form
      className="ohmylms-streak-settings"
      style={{ maxWidth: 800 }}
      onSubmit={async (event) => {
        event.preventDefault();
        if (saving) return;
        setSaving(true);
        setMessage(null);
        try {
          await window.wp.apiFetch({
            path: '/ohmylms/v1/engagement/settings/streak',
            method: 'POST',
            data: settings,
          });
          setMessage({ status: 'success', text: __('Streak settings saved.', 'ohmylms') });
        } catch (error) {
          setMessage({ status: 'error', text: error.message });
        } finally {
          setSaving(false);
        }
      }}
    >
      <h2>{__('Daily learning streaks', 'ohmylms')}</h2>
      {message && (
        <Notice status={message.status} isDismissible={false}>
          {message.text}
        </Notice>
      )}
      <fieldset disabled={saving} style={{ border: 0, padding: 0 }}>
        <ToggleControl
          label={__('Enable learning streaks', 'ohmylms')}
          checked={settings.enable}
          onChange={(value) => set('enable', value)}
        />
        <p>
          {__(
            'One streak across all courses, subjects and learning tracks. Incorrect answers count as participation. Opening content, signing in, empty submissions, purchases and social activity do not count. Points and mastery remain separate.',
            'ohmylms',
          )}
        </p>
        <h3>{__('Qualifying activities', 'ohmylms')}</h3>
        {[
          ['lesson', 'Verified lesson completion'],
          ['quiz', 'Submitted quiz with answers attempted'],
          ['practice', 'Completed skill practice session'],
        ].map(([key, label]) => (
          <ToggleControl
            key={key}
            label={__(label, 'ohmylms')}
            checked={settings[key]}
            onChange={(value) => set(key, value)}
          />
        ))}
        {number(
          'practice_minimum',
          'Minimum answered problems per completed practice session',
          1,
          30,
        )}
        <h3>{__('Streak freezes', 'ohmylms')}</h3>
        <ToggleControl
          label={__('Enable freezes', 'ohmylms')}
          checked={settings.freezes}
          onChange={(value) => set('freezes', value)}
        />
        {number('initial_freezes', 'Initial freezes for new streak participants', 0, 10)}
        {number('maximum_freezes', 'Maximum freeze inventory', 0, 10)}
        {number('refill_days', 'Qualifying learning dates needed for one replacement', 1, 365)}
        <p>
          {__(
            'One freeze protects one missed date without increasing the streak. Freezes are used in date order and must already be available. Only qualifying learning dates earn replacements; no refill credits accumulate while full. Lowering the cap trims inventory; raising initial inventory does not refill existing accounts.',
            'ohmylms',
          )}
        </p>
        <p>
          {__(
            'The learner timezone defaults to the site timezone and stays fixed during an active streak. It can change after a streak ends and 24 hours after the last activity. Past dates are preserved. Enabling streaks starts fresh; no historical activity is imported.',
            'ohmylms',
          )}
        </p>
        <h3>{__('One-time milestone rewards', 'ohmylms')}</h3>
        <p>
          {__(
            'Each milestone is awarded once per learner. Badge rewards use the existing badge system. Optional points require the Bonus Point feature to be enabled; pending rewards retry after it is enabled.',
            'ohmylms',
          )}
        </p>
        {settings.milestones.map((milestone, index) => {
          const update = (key, value) =>
            set(
              'milestones',
              settings.milestones.map((item, position) =>
                position === index ? { ...item, [key]: value } : item,
              ),
            );
          return (
            <fieldset key={index} style={{ padding: 16, marginBottom: 16 }}>
              <legend>
                {__('Milestone', 'ohmylms')} {index + 1}
              </legend>
              <TextControl
                type="number"
                label={__('Qualifying streak days', 'ohmylms')}
                min={1}
                max={10000}
                value={milestone.days}
                onChange={(value) => update('days', value === '' ? '' : Number(value))}
              />
              <SelectControl
                label={__('Badge', 'ohmylms')}
                value={milestone.badge}
                onChange={(value) => update('badge', value)}
                options={[
                  { label: __('No badge', 'ohmylms'), value: '' },
                  ...badges.map((badge) => ({ label: badge.name, value: badge.slug })),
                ]}
              />
              <TextControl
                type="number"
                label={__('Bonus points', 'ohmylms')}
                min={0}
                max={100000}
                value={milestone.points}
                onChange={(value) => update('points', value === '' ? '' : Number(value))}
              />
              <Button
                variant="tertiary"
                isDestructive
                onClick={() =>
                  set(
                    'milestones',
                    settings.milestones.filter((_, position) => position !== index),
                  )
                }
              >
                {__('Remove milestone', 'ohmylms')}
              </Button>
            </fieldset>
          );
        })}
        <Button
          variant="secondary"
          disabled={settings.milestones.length >= 20}
          onClick={() =>
            set('milestones', [...settings.milestones, { days: 7, badge: '', points: 0 }])
          }
        >
          {__('Add milestone', 'ohmylms')}
        </Button>
        <p>
          <Button variant="primary" type="submit" isBusy={saving} disabled={saving}>
            {__('Save streak settings', 'ohmylms')}
          </Button>
        </p>
      </fieldset>
    </form>
  );
}
